const productTags={1:'headphone headphones audio music bluetooth wireless anc',2:'phone phones smartphone mobile android 5g',3:'shoe shoes sneaker sneakers footwear running',4:'watch watches timepiece accessory',5:'serum skincare skin beauty cosmetic vitamin',6:'laptop laptops notebook computer pc oled',7:'coffee maker brewer kitchen travel',8:'bag bags tote handbag fashion',9:'yoga fitness exercise mat gym',10:'honey organic food grocery himalayan',11:'cushion pillow decor sofa home',12:'toy toys blocks kids children learning',13:'television televisions tv smart screen',14:'blender mixer smoothie kitchen appliance',15:'shirt top clothing women fashion',16:'car auto camera dashcam vehicle'};
function editDistance(a,b){const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const tmp=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=tmp}}return row[b.length]}
function matchesSearch(p,query){if(!query)return true;const q=query.toLowerCase().trim();const blob=`${p.name} ${p.brand} ${p.category} ${productTags[p.id]||''}`.toLowerCase();if(blob.includes(q))return true;const tolerance=q.length>=6?2:q.length>3?1:0;return tolerance>0&&blob.split(/[^a-z0-9]+/).some(word=>Math.abs(word.length-q.length)<=tolerance&&editDistance(word,q)<=tolerance)}

const state={cart:JSON.parse(localStorage.getItem('nepamart_cart')||'[]'),wishlist:JSON.parse(localStorage.getItem('nepamart_wishlist')||'[]'),query:'',category:'',rating:0,min:0,max:Infinity,free:false,cod:false,sort:'relevance',visible:10,voucher:false,checkoutStep:1,lang:'en'};
const money=n=>'Rs. '+Math.round(n).toLocaleString('en-IN');
const discount=p=>Math.round((1-p.price/p.old)*100);
const byId=id=>products.find(p=>p.id===Number(id));
const save=()=>{localStorage.setItem('nepamart_cart',JSON.stringify(state.cart));localStorage.setItem('nepamart_wishlist',JSON.stringify(state.wishlist));updateCounts()};

function productCard(p){const liked=state.wishlist.includes(p.id);return `<article class="product-card"><div class="product-image" data-product="${p.id}"><img src="${p.image}" alt="${p.name}" loading="lazy"><span class="discount-badge">-${discount(p)}%</span><button class="wish-button ${liked?'active':''}" data-wish="${p.id}" aria-label="Add ${p.name} to wishlist"><i data-lucide="heart"></i></button></div><div class="product-info"><span class="product-brand">${p.brand}</span><div class="product-name" data-product="${p.id}">${p.name}</div><span class="product-price">${money(p.price)}</span><span class="old-price">${money(p.old)}</span><div class="rating-line"><span class="stars">★★★★★</span><b>${p.rating}</b><span>(${p.reviews}) · ${p.sold>999?(p.sold/1000).toFixed(1)+'k':p.sold} sold</span></div><div class="delivery-line"><i data-lucide="truck"></i>${p.delivery}</div><button class="quick-add" data-add="${p.id}" aria-label="Add ${p.name} to cart"><i data-lucide="plus"></i></button></div></article>`}
function refreshIcons(){window.lucide?.createIcons()}
function renderHome(){document.getElementById('flashProducts').innerHTML=products.slice(0,5).map(productCard).join('');document.getElementById('recommendedProducts').innerHTML=products.slice(5,state.visible).concat(products.slice(0,Math.max(0,state.visible-11))).slice(0,state.visible).map(productCard).join('');document.getElementById('categoryGrid').innerHTML=categories.slice(0,8).map(c=>`<button class="category-tile" data-category="${c.name}"><span style="--tile-bg:${c.bg};--tile-color:${c.color}"><i data-lucide="${c.icon}"></i></span><b>${c.name}</b></button>`).join('');const drawer=document.getElementById('drawerCategories');drawer.innerHTML=categories.map(c=>`<button data-category="${c.name}"><i data-lucide="${c.icon}"></i>${c.name}</button>`).join('');}
function updateCounts(){const count=state.cart.reduce((a,i)=>a+i.qty,0);document.getElementById('cartCount').textContent=count;document.getElementById('mobileCartCount').textContent=count;document.getElementById('wishlistCount').textContent=state.wishlist.length}
function addToCart(id,qty=1){const item=state.cart.find(i=>i.id===Number(id));if(item)item.qty+=qty;else state.cart.push({id:Number(id),qty});save();toast(`${byId(id).name} added to cart`)}
function toggleWish(id){id=Number(id);const i=state.wishlist.indexOf(id);if(i>-1){state.wishlist.splice(i,1);toast('Removed from wishlist')}else{state.wishlist.push(id);toast('Saved to your wishlist')}save();renderHome();if(document.getElementById('productsView').classList.contains('active'))renderListing();refreshIcons()}
function toast(msg){const el=document.createElement('div');el.className='toast';el.innerHTML=`<i data-lucide="check-circle-2"></i>${msg}`;document.getElementById('toastRegion').append(el);refreshIcons();setTimeout(()=>el.remove(),2800)}
function navigate(page){document.querySelectorAll('.page-view').forEach(v=>v.classList.remove('active'));const view=document.getElementById(page+'View')||document.getElementById('homeView');view.classList.add('active');document.querySelectorAll('.mobile-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));if(page==='products')renderListing();if(page==='cart')renderCart();closeDrawer();window.scrollTo({top:0,behavior:'smooth'});refreshIcons()}
function openProduct(id){const p=byId(id);const liked=state.wishlist.includes(p.id);document.getElementById('productModalBody').innerHTML=`<div class="product-detail"><div class="detail-image"><img src="${p.image}" alt="${p.name}"></div><div class="detail-copy"><span class="product-brand">${p.brand} · Official Store</span><h2>${p.name}</h2><div class="detail-rating"><span class="stars">★★★★★</span> <b>${p.rating}</b> · ${p.reviews} ratings · ${p.sold.toLocaleString()} sold</div><div class="detail-price">${money(p.price)}</div><span class="detail-old">${money(p.old)}</span><span class="detail-discount">-${discount(p)}%</span><p class="detail-desc">A carefully selected, authentic product backed by NepaMart buyer protection and a 14-day easy return policy.</p><div class="option-label">Colour</div><div class="swatches"><button style="background:#1d1d1d"></button><button style="background:#d8c7b4"></button><button style="background:#697e90"></button></div><div class="option-label">Option</div><div class="sizes"><button class="active">Standard</button><button>Premium</button></div><div class="detail-delivery"><i data-lucide="map-pin"></i> Deliver to Kathmandu · Estimated 22–24 Oct · ${p.delivery}</div><div class="detail-actions"><button class="buy-now" data-buy="${p.id}">Buy now</button><button class="add-cart" data-add="${p.id}">Add to cart</button><button class="detail-wish ${liked?'active':''}" data-wish="${p.id}"><i data-lucide="heart"></i></button></div></div></div>`;openModal('productModal')}
function openModal(id){document.getElementById('modalBackdrop').classList.add('show');document.getElementById(id).classList.add('show');document.body.style.overflow='hidden';refreshIcons()}
function closeModals(){document.querySelectorAll('.modal').forEach(m=>m.classList.remove('show'));document.getElementById('modalBackdrop').classList.remove('show');document.body.style.overflow=''}
function filtered(){let list=products.filter(p=>matchesSearch(p,state.query)&&(!state.category||p.category===state.category)&&p.price>=state.min&&p.price<=state.max&&p.rating>=state.rating&&(!state.free||p.delivery==='Free delivery')&&(!state.cod||p.cod));if(state.sort==='priceAsc')list.sort((a,b)=>a.price-b.price);if(state.sort==='priceDesc')list.sort((a,b)=>b.price-a.price);if(state.sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(state.sort==='newest')list.sort((a,b)=>b.newest-a.newest);return list}
function renderListing(){const list=filtered();document.getElementById('listingTitle').textContent=state.query?`Results for “${state.query}”`:state.category||'All products';document.getElementById('listingBreadcrumb').textContent=state.category||'All Products';document.getElementById('resultCount').textContent=list.length;document.getElementById('listingProducts').innerHTML=list.map(productCard).join('');document.getElementById('listingProducts').style.display=list.length?'grid':'none';document.getElementById('emptyState').classList.toggle('show',!list.length);document.getElementById('categoryFilters').innerHTML=categories.map(c=>`<label><input type="radio" name="category" value="${c.name}" ${state.category===c.name?'checked':''}> ${c.name}</label>`).join('');const active=[];if(state.category)active.push(state.category);if(state.query)active.push(`Search: ${state.query}`);if(state.free)active.push('Free delivery');if(state.cod)active.push('Cash on delivery');if(state.rating)active.push(`${state.rating}+ stars`);document.getElementById('activeFilters').innerHTML=active.map(x=>`<button data-clear-tag>${x} ×</button>`).join('');refreshIcons()}
function selectCategory(cat){state.category=cat;state.query='';document.getElementById('searchInput').value='';navigate('products')}
function runSearch(){const q=document.getElementById('searchInput').value.trim();state.query=q;state.category='';document.getElementById('searchSuggestions').classList.remove('show');navigate('products')}
function renderCart(){const wrap=document.getElementById('cartList');if(!state.cart.length){wrap.innerHTML=`<div class="empty-cart"><i data-lucide="shopping-bag"></i><h3>Your cart is waiting</h3><p>Find something you love and it will appear here.</p><button data-nav="products">Start shopping</button></div>`}else wrap.innerHTML=state.cart.map(i=>{const p=byId(i.id);return `<article class="cart-item"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p class="cart-meta">${p.brand} · Standard · ${p.delivery}</p><span class="cart-price">${money(p.price)}</span></div><div class="cart-side"><button class="remove-item" data-remove="${p.id}"><i data-lucide="trash-2"></i></button><div class="quantity"><button data-qty="${p.id}" data-change="-1">−</button><span>${i.qty}</span><button data-qty="${p.id}" data-change="1">+</button></div></div></article>`}).join('');const subtotal=state.cart.reduce((s,i)=>s+byId(i.id).price*i.qty,0);const shipping=state.cart.length?Math.max(0,120-state.cart.filter(i=>byId(i.id).delivery==='Free delivery').length*30):0;const off=state.voucher?Math.round(subtotal*.1):0;document.getElementById('cartSubtotal').textContent=money(subtotal);document.getElementById('cartShipping').textContent=money(shipping);document.getElementById('cartDiscount').textContent='− '+money(off);document.getElementById('cartTotal').textContent=money(subtotal+shipping-off);document.getElementById('checkoutButton').disabled=!state.cart.length;refreshIcons()}
function checkout(){if(!state.cart.length)return;state.checkoutStep=1;renderCheckout();openModal('checkoutModal')}
function renderCheckout(){const steps=['Address','Delivery','Payment','Done'];let html=`<div class="checkout-steps">${steps.map((s,i)=>`<div class="checkout-step ${i+1<state.checkoutStep?'done':''} ${i+1===state.checkoutStep?'active':''}"><i>${i+1<state.checkoutStep?'✓':i+1}</i><span>${s}</span></div>`).join('')}</div><div class="checkout-content">`;if(state.checkoutStep===1)html+=`<span class="section-kicker">STEP 1 OF 3</span><h2>Where should we deliver?</h2><p>Use a complete address to help our delivery partner find you faster.</p><form class="checkout-form" id="addressForm"><label>Full name<input required value="Aarav Sharma"></label><label>Mobile number<input required value="9812345678" pattern="9[678][0-9]{8}"></label><label>Province<select><option>Bagmati Province</option><option>Koshi Province</option><option>Gandaki Province</option><option>Lumbini Province</option></select></label><label>District<select><option>Kathmandu</option><option>Lalitpur</option><option>Bhaktapur</option></select></label><label>Municipality<input required value="Kathmandu Metropolitan City"></label><label>Ward number<input required value="4"></label><label class="wide">Street address<input required value="Baluwatar, Kathmandu"></label><label class="wide">Landmark (optional)<input placeholder="Near a school, temple or shop"></label></form>`;if(state.checkoutStep===2)html+=`<span class="section-kicker">STEP 2 OF 3</span><h2>Choose your delivery speed</h2><p>Estimated dates are calculated for your Kathmandu address.</p><div class="checkout-options"><label class="checkout-option active"><input type="radio" checked name="delivery"><i data-lucide="truck"></i><div><b>Standard delivery</b><small>Arrives 22–24 October</small></div><b>Rs. 90</b></label><label class="checkout-option"><input type="radio" name="delivery"><i data-lucide="zap"></i><div><b>Express delivery</b><small>Arrives tomorrow</small></div><b>Rs. 180</b></label></div>`;if(state.checkoutStep===3)html+=`<span class="section-kicker">STEP 3 OF 3</span><h2>How would you like to pay?</h2><p>All online payments are encrypted and securely verified.</p><div class="checkout-options"><label class="checkout-option active"><input type="radio" checked name="payment"><div><b>eSewa</b><small>Pay securely with your eSewa wallet</small></div></label><label class="checkout-option"><input type="radio" name="payment"><div><b>Khalti</b><small>Wallet, mobile banking or card</small></div></label><label class="checkout-option"><input type="radio" name="payment"><div><b>Cash on Delivery</b><small>Pay when your order arrives</small></div></label><label class="checkout-option"><input type="radio" name="payment"><div><b>Fonepay</b><small>Scan and pay through your bank app</small></div></label></div>`;if(state.checkoutStep===4)html+=`<div class="confirmation"><span><i data-lucide="check"></i></span><h2>Your order is confirmed!</h2><p>We’ve sent your receipt and will notify you when the seller ships.</p><div class="order-id">Order #NP-${Math.floor(1000+Math.random()*8999)}-${Math.floor(1000+Math.random()*8999)}</div><br><button data-finish>Track this order</button></div>`;if(state.checkoutStep<4)html+=`<div class="checkout-nav"><button class="checkout-back" data-checkout-back ${state.checkoutStep===1?'disabled':''}>Back</button><button class="checkout-next" data-checkout-next>${state.checkoutStep===3?'Place order':'Continue'}</button></div>`;html+='</div>';document.getElementById('checkoutBody').innerHTML=html;refreshIcons()}
function nextCheckout(){if(state.checkoutStep===1&&!document.getElementById('addressForm').reportValidity())return;state.checkoutStep++;if(state.checkoutStep===4){state.cart=[];save();renderCart()}renderCheckout()}
function closeDrawer(){document.getElementById('sideDrawer').classList.remove('show');document.getElementById('drawerBackdrop').classList.remove('show')}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav)}const cat=e.target.closest('[data-category]');if(cat){e.preventDefault();selectCategory(cat.dataset.category)}const product=e.target.closest('[data-product]');if(product)openProduct(product.dataset.product);const add=e.target.closest('[data-add]');if(add){e.stopPropagation();addToCart(add.dataset.add)}const wish=e.target.closest('[data-wish]');if(wish){e.stopPropagation();toggleWish(wish.dataset.wish)}const buy=e.target.closest('[data-buy]');if(buy){addToCart(buy.dataset.buy);closeModals();navigate('cart');setTimeout(checkout,250)}const rem=e.target.closest('[data-remove]');if(rem){state.cart=state.cart.filter(i=>i.id!==Number(rem.dataset.remove));save();renderCart()}const qty=e.target.closest('[data-qty]');if(qty){const item=state.cart.find(i=>i.id===Number(qty.dataset.qty));item.qty+=Number(qty.dataset.change);if(item.qty<1)state.cart=state.cart.filter(i=>i.id!==item.id);save();renderCart()}if(e.target.closest('[data-close-modal]'))closeModals();if(e.target.id==='modalBackdrop')closeModals();if(e.target.closest('[data-checkout-next]'))nextCheckout();if(e.target.closest('[data-checkout-back]')){state.checkoutStep=Math.max(1,state.checkoutStep-1);renderCheckout()}if(e.target.closest('[data-finish]')){closeModals();navigate('tracking')}if(e.target.closest('[data-clear-tag]')){state.query='';state.category='';state.free=false;state.cod=false;state.rating=0;renderListing()}});
document.getElementById('searchButton').addEventListener('click',runSearch);document.getElementById('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')runSearch()});document.getElementById('searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const matches=q?products.filter(p=>matchesSearch(p,q)).slice(0,5):[];const box=document.getElementById('searchSuggestions');box.innerHTML=matches.map(p=>`<button data-product="${p.id}"><span>${p.name}</span><small>${p.category}</small></button>`).join('');box.classList.toggle('show',matches.length>0)});
document.getElementById('sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderListing()});document.getElementById('applyFilters').addEventListener('click',()=>{state.category=document.querySelector('input[name="category"]:checked')?.value||'';state.rating=Number(document.querySelector('input[name="rating"]:checked')?.value||0);state.min=Number(document.getElementById('minPrice').value||0);state.max=Number(document.getElementById('maxPrice').value||Infinity);state.free=document.getElementById('freeDelivery').checked;state.cod=document.getElementById('codFilter').checked;document.getElementById('filtersPanel').classList.remove('mobile-show');renderListing()});document.getElementById('clearFilters').addEventListener('click',()=>{state.query='';state.category='';state.rating=0;state.min=0;state.max=Infinity;state.free=false;state.cod=false;renderListing()});document.getElementById('emptyReset').addEventListener('click',()=>{state.query='';state.category='';state.min=0;state.max=Infinity;state.rating=0;renderListing()});document.getElementById('filterMobile').addEventListener('click',()=>document.getElementById('filtersPanel').classList.toggle('mobile-show'));
document.getElementById('voucherForm').addEventListener('submit',e=>{e.preventDefault();if(document.getElementById('voucherInput').value.trim().toUpperCase()==='NAMASTE10'){state.voucher=true;renderCart();toast('NAMASTE10 applied — you saved 10%')}else toast('That voucher code is not valid')});document.getElementById('checkoutButton').addEventListener('click',checkout);document.getElementById('accountButton').addEventListener('click',()=>openModal('authModal'));document.getElementById('mobileAccount').addEventListener('click',()=>openModal('authModal'));document.getElementById('wishlistButton').addEventListener('click',()=>{state.query='';state.category='';navigate('products');toast(`${state.wishlist.length} saved item${state.wishlist.length===1?'':'s'} in your wishlist`)});document.getElementById('mobileSearch').addEventListener('click',()=>{navigate('home');setTimeout(()=>document.getElementById('searchInput').focus(),300)});
document.getElementById('authForm').addEventListener('submit',e=>{e.preventDefault();closeModals();toast('Welcome back to NepaMart')});document.getElementById('newsletterForm').addEventListener('submit',e=>{e.preventDefault();e.target.reset();toast('You’re on the list — welcome!')});document.getElementById('trackingForm').addEventListener('submit',e=>{e.preventDefault();document.getElementById('trackingResult').scrollIntoView({behavior:'smooth'});toast('Latest tracking status loaded')});document.getElementById('sellerJoin').addEventListener('click',()=>{openModal('authModal');toast('Create an account to start selling')});
document.getElementById('menuTrigger').addEventListener('click',()=>{document.getElementById('sideDrawer').classList.add('show');document.getElementById('drawerBackdrop').classList.add('show')});document.getElementById('drawerClose').addEventListener('click',closeDrawer);document.getElementById('drawerBackdrop').addEventListener('click',closeDrawer);document.getElementById('categoryTrigger').addEventListener('click',()=>selectCategory(''));
document.getElementById('loadMore').addEventListener('click',()=>{state.visible=Math.min(products.length,state.visible+5);renderHome();refreshIcons();if(state.visible===products.length)document.getElementById('loadMore').style.display='none'});document.getElementById('langToggle').addEventListener('click',e=>{state.lang=state.lang==='en'?'np':'en';e.target.textContent=state.lang==='en'?'नेपाली':'English';toast(state.lang==='np'?'नेपाली भाषा चयन गरियो':'Language changed to English')});
let slide=0;const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('#heroDots button')];function setSlide(i){slide=(i+slides.length)%slides.length;slides.forEach((s,j)=>s.classList.toggle('active',j===slide));dots.forEach((d,j)=>d.classList.toggle('active',j===slide))}document.getElementById('heroPrev').onclick=()=>setSlide(slide-1);document.getElementById('heroNext').onclick=()=>setSlide(slide+1);dots.forEach((d,i)=>d.onclick=()=>setSlide(i));setInterval(()=>setSlide(slide+1),6000);
let remaining=3*3600+24*60+16;setInterval(()=>{remaining=Math.max(0,remaining-1);const h=String(Math.floor(remaining/3600)).padStart(2,'0'),m=String(Math.floor(remaining%3600/60)).padStart(2,'0'),s=String(remaining%60).padStart(2,'0');document.getElementById('countdown').innerHTML=`<b>${h}</b><span>:</span><b>${m}</b><span>:</span><b>${s}</b>`},1000);
renderHome();updateCounts();refreshIcons();
